dict(id="A07", nick="Honigmamas Lasagne", title="Gemüse-Lasagne mit Linsen-Bolognese",
 time=75, active=30, yld="6 Portionen", diet="vegetarisch",
 ing=["1;Zwiebel;G","2;Möhren;G","1;Zucchini;G","2 EL;Olivenöl;V","150 g;rote Linsen;T","2 Dosen (à 400 g);stückige Tomaten;T","300 ml;Gemüsebrühe;V","12;Lasagneplatten;T","500 g;Ricotta;K","200 g;geriebener Mozzarella;K","1 TL;getrockneter Oregano;V"],
 steps=["Zwiebel, Möhren und Zucchini fein würfeln, in Öl 5 Minuten andünsten.","Linsen, Tomaten, Brühe und Oregano zugeben, 15 Minuten köcheln. Salzen.","Ofen auf 180 °C vorheizen. In eine Form abwechselnd Soße, Lasagneplatten und Ricotta schichten, mit Soße abschließen.","Mit Mozzarella bestreuen und 40 Minuten backen, bis die Platten weich sind.","10 Minuten ruhen lassen, dann in Portionen schneiden."],
 why="Die Linsen-Bolognese bringt Eiweiß und Eisen ohne Fleisch, Ricotta Calcium. Lasagne lässt sich gut in Stücken einfrieren und einzeln aufwärmen.",
 fr="Ausgekühlt in Portionen schneiden, einzeln verpacken, bis zu 3 Monate.",
 th="Im Kühlschrank auftauen, abgedeckt bei 180 °C 25 Minuten backen, bis die Mitte heiß ist.",
 al="Glutenhaltiges Getreide (Weizen), Milch, ggf. Ei (Lasagneplatten), Sellerie (Brühe).",
 p="slice of vegetable lentil lasagna with ricotta layers and golden melted mozzarella on a plate, baking dish behind"),
dict(id="A08", nick="Honigmamas Kartoffelglück", title="Kartoffel-Hack-Auflauf mit Lauch",
 time=60, active=20, yld="6 Portionen", diet="mit Fleisch",
 ing=["1 kg;festkochende Kartoffeln;G","400 g;gemischtes Hackfleisch;F","2 Stangen;Lauch;G","1 EL;Rapsöl;V","200 g;Schmand;K","200 ml;Milch;K","2;Eier;K","150 g;geriebener Gouda;K","1 Prise;Muskatnuss;V"],
 steps=["Kartoffeln schälen, in dünne Scheiben schneiden und 5 Minuten in Salzwasser vorgaren, abgießen.","Lauch in Ringe schneiden. Hack in Öl krümelig braten, bis es durchgegart ist, Lauch 5 Minuten mitbraten, salzen.","Ofen auf 190 °C vorheizen. Kartoffeln und Hack-Lauch-Mischung in eine Form schichten.","Schmand, Milch und Eier verquirlen, mit Salz, Pfeffer und Muskat würzen und darübergießen.","Mit Käse bestreuen, 30 Minuten backen, bis der Guss gestockt und goldbraun ist."],
 why="Klassische Hausmannskost, die satt macht: Kartoffeln liefern Energie, Hack und Käse Eiweiß. Viele kennen das Gericht – auch Helfer:innen kochen es gern nach.",
 fr="In Portionen schneiden und bis zu 3 Monate einfrieren.",
 th="Im Kühlschrank auftauen, abgedeckt bei 180 °C 25 Minuten erhitzen, bis es innen dampfend heiß ist.",
 al="Milch, Ei.",
 p="golden potato gratin bake with minced meat and leek in a ceramic dish, a portion cut out, melted cheese crust"),
