dict(id="F07", nick="Honigmamas Bananenbrot", title="Bananenbrot mit Haferflocken & Walnüssen",
 time=65, active=15, yld="1 Kastenform (12 Scheiben)", diet="vegetarisch",
 ing=["3;sehr reife Bananen;G","2;Eier;K","80 ml;Rapsöl;V","3 EL;Ahornsirup;V","200 g;Dinkel-Vollkornmehl;T","80 g;zarte Haferflocken;T","2 TL;Backpulver;T","1 TL;Zimt;V","60 g;Walnüsse;T"],
 steps=["Ofen auf 175 °C vorheizen, Kastenform mit Backpapier auslegen.","Bananen zerdrücken, mit Eiern, Öl und Ahornsirup verrühren.","Mehl, Haferflocken, Backpulver und Zimt mischen und kurz unterrühren. Gehackte Walnüsse unterheben.","Teig in die Form füllen und 50 Minuten backen (Stäbchenprobe).","Vollständig auskühlen lassen und in Scheiben schneiden."],
 why="Reife Bananen süßen fast von allein, Vollkorn und Hafer halten lange satt, Walnüsse liefern Omega-3-Fettsäuren. Eine Scheibe geht morgens mit einer Hand.",
 fr="In Scheiben schneiden, mit Backpapier dazwischen bis zu 3 Monate einfrieren.",
 th="Einzelne Scheiben gefroren in den Toaster oder 20 Minuten bei Zimmertemperatur auftauen.",
 al="Ei, glutenhaltiges Getreide (Dinkel, Hafer), Schalenfrüchte (Walnüsse).",
 p="sliced banana oat walnut bread on a wooden board, one slice toasted with butter, ripe bananas next to it"),
dict(id="F08", nick="Honigmamas Spinatwölkchen", title="Ei-Gemüse-Muffins mit Spinat & Feta",
 time=30, active=10, yld="12 Stück", diet="vegetarisch",
 ing=["8;Eier;K","100 ml;Milch;K","100 g;Babyspinat;G","1;rote Paprika;G","4;Frühlingszwiebeln;G","100 g;Feta;K","1 TL;Rapsöl;V"],
 steps=["Ofen auf 180 °C vorheizen, Muffinform mit Öl einfetten oder mit Papierförmchen auslegen.","Spinat grob hacken, Paprika fein würfeln, Frühlingszwiebeln in Ringe schneiden.","Eier und Milch verquirlen, leicht salzen. Gemüse und zerbröselten Feta unterrühren.","Masse auf 12 Mulden verteilen und 20 Minuten backen, bis die Muffins vollständig gestockt sind.","In der Form 5 Minuten abkühlen lassen, dann herauslösen."],
 why="Ein herzhaftes Frühstück mit viel Eiweiß, das sich nach kurzen Nächten in der Mikrowelle aufwärmen lässt. Das Gemüse bringt Folat und Vitamin C.",
 fr="Vollständig ausgekühlt einzeln einfrieren, bis zu 2 Monate.",
 th="Gefroren 60–90 Sekunden in der Mikrowelle oder 12 Minuten bei 170 °C im Ofen erhitzen, bis sie innen heiß sind.",
 al="Ei, Milch.",
 p="savory egg muffins with spinach, red pepper and feta on a cooling rack, one broken open, morning light"),
dict(id="F09", nick="Honigmamas Pfannküchlein", title="Hafer-Apfel-Pancakes zum Toasten",
 time=30, active=25, yld="16 Stück", diet="vegetarisch",
 ing=["200 g;zarte Haferflocken;T","300 ml;Milch;K","2;Eier;K","1;Apfel;G","1 TL;Backpulver;T","1 TL;Zimt;V","1 EL;Rapsöl;V"],
 steps=["Haferflocken mit Milch im Mixer zu einem dicken Teig mixen.","Eier, Backpulver und Zimt zugeben und kurz weitermixen. Apfel fein raspeln und unterrühren. 5 Minuten quellen lassen.","Eine Pfanne mit wenig Öl erhitzen, je 2 EL Teig hineingeben.","Pancakes je Seite 2–3 Minuten goldbraun backen, bis sie durchgebacken sind.","Auf einem Gitter auskühlen lassen."],
 why="Ohne Zuckerzusatz, mit Hafer für lang anhaltende Energie und Apfel für natürliche Süße. Aus der Truhe direkt in den Toaster – schneller geht Frühstück kaum.",
 fr="Mit Backpapier dazwischen bis zu 3 Monate einfrieren.",
 th="Gefroren 2 Durchgänge im Toaster oder 1 Minute je Seite in der Pfanne.",
 al="Ei, Milch, glutenhaltiges Getreide (Hafer).",
 p="stack of small oat apple pancakes with yogurt, apple slices and a drizzle of maple syrup, toaster in the background"),
